select ${columns} from performance_customer_info p
left join sys_user u on p.credit_manager_job_number = u.manager_num

    ${params.dataScope}
    and p.id is not null
    and p.customer_nm like concat('%', #{customerNm}, '%')
    and p.customer_name like concat('%',
        #{customerName},
        '%')

    and p.customer_phone like concat('%',
        #{customerPhone}, '%')

    and p.customer_level in

            #{customerLevel}


    and p.work_unit like concat('%', #{workUnit}, '%')
    and p.job like concat('%', #{job}, '%')
    and p.deposit between #{minDeposit} and #{maxDeposit}

    and p.deposit >= #{minDeposit}
    and p.deposit <= #{maxDeposit}
    and p.loan between #{minLoan} and #{maxLoan}
    and p.loan >= #{minLoan}
    and p.loan <= #{maxLoan}
    and p.finance between #{minFinance} and #{maxFinance}

    and p.finance >= #{minFinance}
    and p.finance <= #{maxFinance}
    and p.property between #{minProperty} and
        #{maxProperty}

    and p.property >= #{minProperty}
    and p.property <= #{maxProperty}
    and p.belong_grid_code = #{belongGridCode}
    and p.grid_manager = #{gridManager}
    and p.customer_type = #{customerType}
    and p.customer_type in

