update performance_customer_info
deposit = #{deposit}, loan = #{loan}, finance = #{finance}, property = #{property}, update_time = #{updateTime},
where customer_nm = #{customerNm} and credit_manager_job_number = #{creditManagerJobNumber}

mapper.select:


    and customer_nm like concat('%',#{customerNm },'%')
    and customer_name like
        concat('%',#{customerName },'%')

    and customer_identity like
        concat('%',#{customerIdentity },'%')

    and customer_phone like
        concat('%',#{customerPhone },'%')

    and customer_level = #{customerLevel }
