select pci.id, pci.customer_nm, pci.customer_name, pci.customer_phone, pci.customer_identity, pci.customer_type, pci.customer_level, pci.customer_address, pci.work_unit, pci.job, pci.deposit, pci.loan, pci.finance, pci.property, pci.belong_grid_code, pci.belong_grid_name, pci.grid_manager, pci.branch_bank, pci.separate_bank, pci.credit_manager, pci.credit_manager_job_number, pci.gender, birthday, pci.age, pci.marital_status, pci.legal_person_identity_num, pci.legal_person_name, pci.legal_person_phone, pci.business_address, pci.point,su.nick_name as grid_manager_name from performance_customer_info pci left join sys_user su on pci.grid_manager = su.manager_num
and pci.id = #{customerId} and pci.customer_identity = #{customerIdentity}
limit 50

select bank_agency_name,count(*) as count from performance_customer_info p left join custom_group_customer c on p.id = c.customer_id
and c.custom_group_id = #{groupId}
group by bank_agency_name

